head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > E > onviewchange]<br/>컴포넌트에서 사용자의 조작에 의해 아이템들의 선택 상태가 변경되면 발생합니다.",
    "validation" : [        
        "컴포넌트에서 사용자의 조작에 의해 아이템들의 선택 상태가 변경되면 발생합니다.",
        "아이템들의 선택이 변경되지 않은 경우 onviewchange 이벤트는 발생하지 않습니다.",
        "info 파라미터로 전체 아이템들의 선택 상태(변경 전/후) 정보가 객체로 전달됩니다.",
        "info.oldInfo 속성값으로 allOption 속성으로 추가된 아이템을 포함하여 전체 아이템 갯수만큼 객체를 배열로 반환합니다.",
        "배열의 각 객체는 아이템의 변경 전 선택 상태 정보를 갖습니다.",
        "info.oldInfo.index 속성값으로 아이템의 인덱스값을 갖습니다.",
        "info.oldInfo.label 속성값으로 포맷이 적용된 아이템의 Label 값을 갖습니다. (displayMode 속성 등에 의해 포맷이 적용됨)",
        "info.oldInfo.value 속성값으로 아이템의 Value 값을 갖습니다.",
        "info.oldInfo.checked 속성값으로 아이템의 변경 전 선택 상태를 true/false 값으로 갖습니다.",        
        "info.newInfo 속성값으로 allOption 속성으로 추가된 아이템을 포함하여 전체 아이템 갯수만큼 객체를 배열로 반환합니다.",
        "배열의 각 객체는 아이템의 변경 후 선택 상태 정보를 갖습니다.",
        "info.newInfo.index 속성값으로 아이템의 인덱스값을 갖습니다.",
        "info.newInfo.label 속성값으로 포맷이 적용된 아이템의 Label 값을 갖습니다. (displayMode 속성 등에 의해 포맷이 적용됨)",
        "info.newInfo.value 속성값으로 아이템의 Value 값을 갖습니다.",
        "info.newInfo.checked 속성값으로 아이템의 변경 후 선택 상태를 true/false 값으로 갖습니다.",             
        "info.oldValue 속성값으로 변경 전에 선택되어 있던 아이템들의 Value 값을 separator 속성값으로 구분한 값을 갖습니다.",
        "선택되어 있던 아이템이 한 개인 경우 구분자 없이 해당 아이템의 Value 값만 갖습니다.",
        "기존에 선택된 아이템이 없는 경우 ''(Empty String)값을 갖습니다.",
        "info.newValue 속성값으로 변경 후에 선택된 아이템들의 Value 값을 separator 속성값으로 구분한 값을 갖습니다.",
        "선택된 아이템이 한 개인 경우 구분자 없이 해당 아이템의 Value 값만 갖습니다.",
        "모든 아이템이 선택되지 않은 경우 ''(Empty String)값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onviewchange"]);

    // comp 생성
    $c.gcm.createBasicCheckComboBox('', eList);
}



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldInfo : " + info.oldInfo);    

    for (let i =0; i < 3; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldInfo.index["+i+"] : " + info.oldInfo[i].index);
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldInfo.label["+i+"] : " + info.oldInfo[i].label);
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldInfo.value["+i+"] : " + info.oldInfo[i].value);
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldInfo.checked["+i+"] : " + info.oldInfo[i].checked);
    }

    wf_body_bottom.getObj("scwin").setReturnValue("info.newInfo : " + info.newInfo);

    for (let i =0; i < 3; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("info.newInfo.index["+i+"] : " + info.newInfo[i].index);
        wf_body_bottom.getObj("scwin").setReturnValue("info.newInfo.label["+i+"] : " + info.newInfo[i].label);
        wf_body_bottom.getObj("scwin").setReturnValue("info.newInfo.value["+i+"] : " + info.newInfo[i].value);
        wf_body_bottom.getObj("scwin").setReturnValue("info.newInfo.checked["+i+"] : " + info.newInfo[i].checked);
    }

    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}
